 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    # Each outlined object is a separate 4-neighbor component.
    seen = set()
    components = []
    for p in pts:
        if p in seen:
            continue
        stack = [p]
        seen.add(p)
        comp = []
        while stack:
            r, c = stack.pop()
            comp.append((r, c))
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                rr, cc = q
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 5 and q not in seen:
                    seen.add(q)
                    stack.append(q)
        components.append(comp)
    for comp in components:
        r0 = min(r for r, _ in comp)
        r1 = max(r for r, _ in comp)
        c0 = min(c for _, c in comp)
        c1 = max(c for _, c in comp)
        # Fill the interior of the open rectangular outline with color 2.
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if grid[r][c] == 0:
                    out[r][c] = 2
        # The break in the top edge sends a color-2 ray left to the grid edge.
        gaps = [c for c in range(c0, c1 + 1) if grid[r0][c] == 0]
        if gaps and r0 > 0:
            gap = gaps[0]
            for c in range(gap + 1):
                if grid[r0 - 1][c] == 0:
                    out[r0 - 1][c] = 2
    return out
